package com.weatherapp.servlet;
import com.weatherapp.db.Database;import com.weatherapp.security.PasswordUtil;import com.weatherapp.util.Json;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet("/api/register") public class RegisterServlet extends BaseServlet{
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{try{Map<String,Object> b=Json.M.readValue(Json.body(req),Map.class);String name=String.valueOf(b.getOrDefault("fullName","" )).trim(),mobile=String.valueOf(b.getOrDefault("mobile","" )).trim(),email=String.valueOf(b.getOrDefault("email","" )).trim(),pw=String.valueOf(b.getOrDefault("password",""));int city=Integer.parseInt(String.valueOf(b.getOrDefault("cityId","0")));if(name.isBlank()||mobile.isBlank()||email.isBlank()||city<=0||pw.length()<6)throw new Exception("Enter all details; password must be at least 6 characters.");try(Connection c=Database.getConnection()){try(PreparedStatement q=c.prepareStatement("SELECT COUNT(*) FROM Users WHERE Mobile=? AND IsActive=True")){q.setString(1,mobile);try(ResultSet r=q.executeQuery()){r.next();if(r.getInt(1)>0)throw new Exception("Mobile number is already registered.");}}String salt=PasswordUtil.salt(),hash=PasswordUtil.hash(pw,salt);try(PreparedStatement p=c.prepareStatement("INSERT INTO Users(FullName,Mobile,Email,CityID,PasswordHash,PasswordSalt,IsActive,CreatedOn) VALUES(?,?,?,?,?,?,TRUE,?)")){p.setString(1,name);p.setString(2,mobile);p.setString(3,email);p.setInt(4,city);p.setString(5,hash);p.setString(6,salt);p.setTimestamp(7,new Timestamp(System.currentTimeMillis()));p.executeUpdate();}}Json.write(res,Map.of("ok",true));}catch(Exception e){res.setStatus(400);Json.write(res,Map.of("ok",false,"message",e.getMessage()));}}
}
